{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-2/run-2/suite-a/helpers/api.ts","content":"import { expect, type APIRequestContext } from '@playwright/test';
import { ADDRESS, CARD } from '../data/test-data';

export interface Customer {
  email: string;
  password: string;
}

export interface Session {
  token: string;
  basketId: number;
}

/** Creates a unique customer account through the REST API. */
export async function registerCustomer(request: APIRequestContext, prefix: string): Promise<Customer> {
  const unique = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const customer = { email: `${prefix}-${unique}@example.test`, password: `Passw0rd!${prefix}` };
  const response = await request.post('/api/Users', {
    data: {
      email: customer.email,
      password: customer.password,
      passwordRepeat: customer.password,
      securityQuestion: { id: 1 },
      securityAnswer: 'test',
    },
  });
  expect(response.status(), await response.text()).toBe(201);
  return customer;
}

/** Shop REST API calls of one logged-in customer, used to prepare preconditions. */
export class ShopApi {
  private constructor(
    private readonly request: APIRequestContext,
    readonly session: Session,
  ) {}

  static async login(request: APIRequestContext, customer: Customer): Promise<ShopApi> {
    const response = await request.post('/rest/user/login', {
      data: { email: customer.email, password: customer.password },
    });
    expect(response.ok(), await response.text()).toBeTruthy();
    const { authentication } = await response.json();
    return new ShopApi(request, { token: authentication.token, basketId: authentication.bid });
  }

  private get headers() {
    return { Authorization: `Bearer ${this.session.token}` };
  }

  async addAddress(): Promise<number> {
    const response = await this.request.post('/api/Addresss', { headers: this.headers, data: ADDRESS });
    expect(response.ok(), await response.text()).toBeTruthy();
    return (await response.json()).data.id;
  }

  async addCard(): Promise<number> {
    const response = await this.request.post('/api/Cards', { headers: this.headers, data: CARD });
    expect(response.ok(), await response.text()).toBeTruthy();
    return (await response.json()).data.id;
  }

  async addToBasket(productId: number, quantity: number): Promise<void> {
    const response = await this.request.post('/api/BasketItems', {
      headers: this.headers,
      data: { ProductId: productId, BasketId: String(this.session.basketId), quantity },
    });
    expect(response.ok(), await response.text()).toBeTruthy();
  }

  /** Adds money to the wallet, paid with a saved card. Returns the new balance. */
  async topUpWallet(amount: number, cardId: number): Promise<number> {
    const response = await this.request.put('/rest/wallet/balance', {
      headers: this.headers,
      data: { balance: amount, paymentId: cardId },
    });
    expect(response.ok(), await response.text()).toBeTruthy();
    return (await response.json()).data;
  }

  async walletBalance(): Promise<number> {
    const response = await this.request.get('/rest/wallet/balance', { headers: this.headers });
    expect(response.ok(), await response.text()).toBeTruthy();
    return (await response.json()).data;
  }
}
"}

{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-2/run-2/suite-a/tests/fixtures.ts","content":"import { test as base, expect } from '@playwright/test';
import { registerCustomer, ShopApi, type Customer } from '../helpers/api';
import { LoginPage } from '../pages/LoginPage';
import { NavBar } from '../pages/NavBar';
import { SearchPage } from '../pages/SearchPage';
import { BasketPage } from '../pages/BasketPage';
import {
  AddressSelectPage,
  DeliveryMethodPage,
  OrderCompletionPage,
  OrderSummaryPage,
  PaymentPage,
} from '../pages/CheckoutPages';
import { OrderHistoryPage, WalletPage } from '../pages/AccountPages';

interface Pages {
  loginPage: LoginPage;
  navBar: NavBar;
  searchPage: SearchPage;
  basketPage: BasketPage;
  addressPage: AddressSelectPage;
  deliveryPage: DeliveryMethodPage;
  paymentPage: PaymentPage;
  orderSummaryPage: OrderSummaryPage;
  orderCompletionPage: OrderCompletionPage;
  orderHistoryPage: OrderHistoryPage;
  walletPage: WalletPage;
}

interface Fixtures extends Pages {
  /** A new customer account, unique for each test. */
  customer: Customer;
  /** REST API of the customer, to prepare preconditions. */
  api: ShopApi;
  /** Logs the customer in through the login page and waits for the product list. */
  loginAsCustomer: () => Promise<void>;
}

export const test = base.extend<Fixtures>({
  page: async ({ page, context, baseURL }, use) => {
    // Hide the cookie banner.
    await context.addCookies([{ name: 'cookieconsent_status', value: 'dismiss', url: baseURL! }]);
    await use(page);
  },
  customer: async ({ request }, use, testInfo) => {
    const prefix = testInfo.titlePath.find((t) => /^TC-\d+/.test(t))?.slice(0, 5).toLowerCase() ?? 'test';
    await use(await registerCustomer(request, prefix));
  },
  api: async ({ request, customer }, use) => {
    await use(await ShopApi.login(request, customer));
  },
  loginAsCustomer: async ({ page, customer }, use) => {
    await use(async () => {
      const loginPage = new LoginPage(page);
      await loginPage.goto();
      await loginPage.login(customer.email, customer.password);
      await expect(page).toHaveURL(/#\/search/);
    });
  },
  loginPage: async ({ page }, use) => use(new LoginPage(page)),
  navBar: async ({ page }, use) => use(new NavBar(page)),
  searchPage: async ({ page }, use) => use(new SearchPage(page)),
  basketPage: async ({ page }, use) => use(new BasketPage(page)),
  addressPage: async ({ page }, use) => use(new AddressSelectPage(page)),
  deliveryPage: async ({ page }, use) => use(new DeliveryMethodPage(page)),
  paymentPage: async ({ page }, use) => use(new PaymentPage(page)),
  orderSummaryPage: async ({ page }, use) => use(new OrderSummaryPage(page)),
  orderCompletionPage: async ({ page }, use) => use(new OrderCompletionPage(page)),
  orderHistoryPage: async ({ page }, use) => use(new OrderHistoryPage(page)),
  walletPage: async ({ page }, use) => use(new WalletPage(page)),
});

export { expect };
"}

