{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-2/run-2/suite-a/tests/tc-03-basket-quantity-and-remove.spec.ts","content":"import { test, expect } from './fixtures';
import { PRODUCTS } from '../data/test-data';
import { itemsTotal, price } from '../helpers/money';

test.describe('TC-03: Change the quantity and remove a product in the basket', () => {
  test('TC-03 plus, minus and trash buttons update the basket', async ({
    api,
    loginAsCustomer,
    basketPage,
    navBar,
  }) => {
    const a = PRODUCTS.raspberryJuice;
    const b = PRODUCTS.eggfruitJuice;
    await api.addToBasket(a.id, 1);
    await api.addToBasket(b.id, 1);
    await loginAsCustomer();

    const expectBasket = async (qtyA: number, qtyB: number) => {
      await expect(basketPage.table.quantity(a.name)).toHaveText(String(qtyA));
      await expect(basketPage.table.quantity(b.name)).toHaveText(String(qtyB));
      const total = itemsTotal([
        { price: a.price, quantity: qtyA },
        { price: b.price, quantity: qtyB },
      ]);
      await expect(basketPage.totalPrice).toHaveText(`Total Price: ${price(total)}`);
      await expect(navBar.basketCounter).toHaveText(String(qtyA + qtyB));
    };

    await test.step('1. Open the basket', async () => {
      await basketPage.goto();
      await expect(basketPage.table.rows).toHaveCount(2);
      await expectBasket(1, 1);
    });

    await test.step('2. Click plus on product A', async () => {
      await basketPage.plusButton(a.name).click();
      await expectBasket(2, 1);
    });

    await test.step('3. Click minus on product A', async () => {
      await basketPage.minusButton(a.name).click();
      await expectBasket(1, 1);
    });

    await test.step('4. Click minus on product A again: the quantity stays 1', async () => {
      await basketPage.minusButton(a.name).click();
      // Wait for any basket update request to finish before reading the state.
      await basketPage.totalPrice.page().waitForLoadState('networkidle');
      await expect(basketPage.table.row(a.name)).toBeVisible();
      await expectBasket(1, 1);
    });

    await test.step('5. Click trash on product A', async () => {
      await basketPage.trashButton(a.name).click();
      await expect(basketPage.table.row(a.name)).toHaveCount(0);
      await expect(basketPage.table.rows).toHaveCount(1);
      await expect(basketPage.table.quantity(b.name)).toHaveText('1');
      await expect(basketPage.totalPrice).toHaveText(`Total Price: ${price(b.price)}`);
      await expect(navBar.basketCounter).toHaveText('1');
    });
  });
});
"}

{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-2/run-2/suite-a/tests/tc-04-purchase-limit.spec.ts","content":"import { test, expect } from './fixtures';
import { PRODUCTS, PURCHASE_LIMIT } from '../data/test-data';
import { itemsTotal, price } from '../helpers/money';

test.describe('TC-04: Purchase limit for one product', () => {
  test('TC-04 basket holds at most the limit of a limited product', async ({
    loginAsCustomer,
    searchPage,
    basketPage,
    navBar,
  }) => {
    const product = PRODUCTS.appleJuice;
    const limitMessage = `You can order only up to ${PURCHASE_LIMIT} items of this product.`;
    const totalFor = (quantity: number) => `Total Price: ${price(itemsTotal([{ price: product.price, quantity }]))}`;
    await loginAsCustomer();

    await test.step('1. Add the product from the product list', async () => {
      await searchPage.goto();
      await searchPage.addToBasket(product.name);
      await expect(searchPage.snackBar).toHaveText(`Placed ${product.name} into basket.`);
      await expect(navBar.basketCounter).toHaveText('1');
    });

    await test.step(`2. Click plus until the quantity is ${PURCHASE_LIMIT}`, async () => {
      await basketPage.goto();
      for (let quantity = 2; quantity <= PURCHASE_LIMIT; quantity++) {
        await basketPage.plusButton(product.name).click();
        await expect(basketPage.table.quantity(product.name)).toHaveText(String(quantity));
      }
      await expect(basketPage.totalPrice).toHaveText(totalFor(PURCHASE_LIMIT));
      await expect(basketPage.snackBar).toHaveCount(0);
    });

    await test.step('3. Click plus one more time', async () => {
      await basketPage.plusButton(product.name).click();
      await expect(basketPage.snackBar).toHaveText(limitMessage);
    });

    await test.step('4. Read the basket', async () => {
      await expect(basketPage.table.quantity(product.name)).toHaveText(String(PURCHASE_LIMIT));
      await expect(basketPage.totalPrice).toHaveText(totalFor(PURCHASE_LIMIT));
      await expect(navBar.basketCounter).toHaveText(String(PURCHASE_LIMIT));
    });

    await test.step('5. Add the product again from the product list', async () => {
      await searchPage.goto();
      await searchPage.dismissMessages();
      await searchPage.addToBasket(product.name);
      await expect(searchPage.snackBar).toHaveText(limitMessage);
      await expect(navBar.basketCounter).toHaveText(String(PURCHASE_LIMIT));
    });
  });
});
"}

{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-2/run-2/suite-a/tests/tc-05-valid-coupon.spec.ts","content":"import { test, expect } from './fixtures';
import { ADDRESS, CARD_LAST_DIGITS, DELIVERY, PRODUCTS } from '../data/test-data';
import { appDate, couponCode } from '../helpers/coupon';
import { discount, itemsTotal, orderTotal, price } from '../helpers/money';

const COUPON_DISCOUNT = 10;

test.describe('TC-05: Valid coupon on the payment step', () => {
  test('TC-05 coupon of the current month lowers the price of the products', async ({
    page,
    request,
    api,
    loginAsCustomer,
    basketPage,
    addressPage,
    deliveryPage,
    paymentPage,
    orderSummaryPage,
  }) => {
    const product = PRODUCTS.eggfruitJuice;
    const quantity = 2;
    const delivery = DELIVERY.oneDay;
    const coupon = couponCode(await appDate(request), COUPON_DISCOUNT);
    const items = itemsTotal([{ price: product.price, quantity }]);
    const promotion = discount(items, COUPON_DISCOUNT);

    await api.addAddress();
    await api.addCard();
    await api.addToBasket(product.id, quantity);
    await loginAsCustomer();

    await test.step('1. Open the basket and click Checkout', async () => {
      await basketPage.goto();
      await basketPage.checkout();
      await expect(addressPage.title).toBeVisible();
      await expect(addressPage.address(ADDRESS.fullName)).toContainText(ADDRESS.streetAddress);
    });

    await test.step('2. Select the saved address and continue', async () => {
      await addressPage.selectAndContinue(ADDRESS.fullName);
      await expect(deliveryPage.title).toBeVisible();
      for (const method of [DELIVERY.oneDay, DELIVERY.fast, DELIVERY.standard]) {
        await expect(deliveryPage.price(method.name)).toHaveText(price(method.price));
      }
    });

    await test.step(`3. Select ${delivery.name} and continue`, async () => {
      await deliveryPage.selectAndContinue(delivery.name);
      await expect(paymentPage.title).toBeVisible();
      await expect(paymentPage.card(CARD_LAST_DIGITS)).toBeVisible();
      await expect(paymentPage.couponPanel).toContainText('Add a coupon');
    });

    await test.step('4. Redeem the coupon of the current month', async () => {
      await paymentPage.openCouponPanel();
      await paymentPage.redeemCoupon(coupon);
      await expect(paymentPage.couponConfirmation).toHaveText(
        `Your discount of ${COUPON_DISCOUNT}% will be applied during checkout.`,
      );
      await expect(paymentPage.couponError).toHaveCount(0);
    });

    await test.step('5. Select the saved card and continue', async () => {
      await paymentPage.selectCardAndContinue(CARD_LAST_DIGITS);
      await expect(page).toHaveURL(/#\/order-summary/);
      await expect(orderSummaryPage.items).toHaveText(price(items));
      await expect(orderSummaryPage.delivery).toHaveText(price(delivery.price));
      await expect(orderSummaryPage.promotion).toHaveText(price(promotion));
      await expect(orderSummaryPage.totalPrice).toHaveText(price(orderTotal(items, delivery.price, promotion)));
    });
  });
});
"}

{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-2/run-2/suite-a/tests/tc-06-invalid-and-expired-coupon.spec.ts","content":"import { test, expect } from './fixtures';
import { ADDRESS, CARD_LAST_DIGITS, DELIVERY, PRODUCTS } from '../data/test-data';
import { appDate, couponCode, previousMonth } from '../helpers/coupon';
import { itemsTotal, orderTotal, price } from '../helpers/money';

const INVALID_CODE = 'abcdefghij';
const COUPON_DISCOUNT = 10;

test.describe('TC-06: Invalid coupon and expired coupon', () => {
  test('TC-06 invalid and expired coupons give no discount', async ({
    page,
    request,
    api,
    loginAsCustomer,
    basketPage,
    addressPage,
    deliveryPage,
    paymentPage,
    orderSummaryPage,
  }) => {
    const product = PRODUCTS.eggfruitJuice;
    const quantity = 2;
    const delivery = DELIVERY.oneDay;
    const expiredCoupon = couponCode(previousMonth(await appDate(request)), COUPON_DISCOUNT);
    const items = itemsTotal([{ price: product.price, quantity }]);

    await api.addAddress();
    await api.addCard();
    await api.addToBasket(product.id, quantity);
    await loginAsCustomer();

    await test.step('1. Checkout and select the saved address', async () => {
      await basketPage.goto();
      await basketPage.checkout();
      await addressPage.selectAndContinue(ADDRESS.fullName);
